$q=new WP_Query(array('post_type'=>'post','posts_per_page'=>3,'post_status'=>'publish')); ?><section <?php echo get_block_wrapper_attributes(array('class'=>'wugweb-section wugweb-recent-thoughts')); ?>><p class="wugweb-section__eyebrow">Recent thoughts</p><h2><?php echo esc_html($attributes['heading']??'Ideas for the next decision.'); ?></h2><div class="wugweb-section__grid"><?php if($q->have_posts()): while($q->have_posts()):$q->the_post(); ?><article class="wugweb-section__card"><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),20)); ?></p></article><?php endwhile; wp_reset_postdata(); else: ?><article class="wugweb-section__card"><h3>Recent thoughts are ready for publishing.</h3><p>Add posts to populate this section.</p></article><?php endif; ?></div></section>